function makeRenderItem(xDim, yDim, valDim, dataExtent) {
  return function(params, api) {
    const xval = api.value(xDim);
    const yval = api.value(yDim);
    const labelVal = api.value(valDim);
    const rect = api.layout([xval, yval]).rect;
    if (!rect) {
      return;
    }
